// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(uint256 strike, uint256 nonce) public {
        strike = bound(strike, 1, 1e30);

        // helper acts as maker (ERC-1271 signer) and as baseAsset token that
        // accepts transferFrom calls (empty returndata passes safeTransferFrom)
        Signer maker = new Signer();

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: false,
            isLong: false,
            baseAsset: address(maker),
            strike: strike,
            premium: 1,
            duration: 1 days,
            expiration: block.timestamp + 1,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new PuttyV2.ERC20Asset[](0),
            erc721Assets: new PuttyV2.ERC721Asset[](0)
        });

        uint256 positionId = c.fillOrder(order, "", new uint256[](0));

        // the taker (this test contract) received the position; as its owner it
        // must be able to transfer it away. On the buggy version the position
        // was minted as unowned, so transferFrom reverts (WRONG_FROM).
        vm.prank(address(this));
        bool ok;
        try c.transferFrom(address(this), address(0xdead), positionId) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract Signer {
    function isValidSignature(bytes32, bytes calldata) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }

    fallback() external payable {}
}
